import React from 'react';
import { Link } from 'react-router-dom';

const Home = () => {
  return (
    <div className="bg-gray-800 text-white min-h-screen">
      <header className="flex justify-between items-center p-4">
        <nav className="space-x-4">
        <div className="text-2xl">My Logo</div>
          <Link to="/" className="hover:text-gray-400">Home</Link>
          <Link to="/about" className="hover:text-gray-400">About</Link>
          <Link to="/photography" className="hover:text-gray-400">Photography</Link>
          <Link to="/portfolio" className="hover:text-gray-400">Portfolio</Link>
        </nav>
      </header>

      <main className="p-8">
        <h1>Welcome to my homepage</h1>
        <p>This is a simple page using React and Tailwind CSS.</p>
      </main>
    </div>
  );
};

export default Home;
